import sys

def getline() -> str:
	return sys.stdin.readline().strip()

def solve():
	(n, x, y) = list(map(int, getline().split()))
	a = list(map(int, getline().split()))
	odds = 0
	for e in a:
		if e % 2 == 1:
			odds += 1
	if x % 2 == y % 2:
		if odds % 2 == 0:
			print('Alice')
			return
		else:
			print('Bob')
			return
	elif odds % 2 == 0:
		print('Bob')
		return
	else:
		print('Alice')
		return
t = int(getline())
for _ in range(t):
	solve()
